#include <iostream>
#include <string_view>

bool valid_quantity(int quantity) { return quantity >= 0 && quantity <= 100000; }
int main() {
    constexpr std::string_view build_mode = "release";
    std::cout << build_mode << ", valid=" << std::boolalpha << valid_quantity(12) << '\n';
}
